package net.minecraft.world.item;public class ItemStack {public String gunId,ammoId,mode;public int rounds;public boolean chambered;public Item item;public int count;public ItemStack(Item item,int count){this.item=item;this.count=count;}public Item getItem(){return item;}public Object getHoverName(){return new Name(gunId!=null?gunId:ammoId!=null?ammoId:item.id());}public record Name(String value){public String getString(){return value;}}public int getCount(){return count;}public int getMaxStackSize(){return item.id().contains("kinetic_gun")||item.id().endsWith("_axe")||item.id().endsWith("_chestplate")?1:64;}}